<script setup lang="ts">
import { nextTick, onUnmounted, ref, watch } from 'vue';
import { ElMessageBox } from 'element-plus';
import type { components } from '@ism/api-client';
import { useSessionStore } from '../stores/session';
const props=defineProps<{application:components['schemas']['AdmissionApplication']}>();const session=useSessionStore();
const rows=ref<components['schemas']['AdmissionPublicResult'][]>([]),canPublish=ref(false),busy=ref(false),error=ref(''),comment=ref(''),notice=ref(''),pending=ref<components['schemas']['PublishAdmissionResult']>();
const panel=ref<HTMLElement>();const names={APPROVED:'准入通过',REJECTED:'准入拒绝',REVISION_REQUIRED:'需要补正'};const abort=new AbortController();let disposed=false,generation=0;
async function fail(text:string){if(disposed)return;error.value=text;await nextTick();panel.value?.focus();}
async function load(){if(disposed)return;const current=++generation;busy.value=true;error.value='';try{const result=await session.client.GET('/admissions/{id}/public-results',{params:{path:{id:props.application.id}},signal:abort.signal});if(disposed||current!==generation)return;if(!result.data)throw new Error(result.error?.error.message??'发布记录读取失败');rows.value=result.data.data.items;canPublish.value=result.data.data.canPublish;if(pending.value)notice.value='已更新发布记录；尚未确认的操作可原样重试。';}catch(e){if(current===generation)await fail(e instanceof Error?e.message:'读取失败');}finally{if(!disposed&&current===generation)busy.value=false;}}
watch(()=>[props.application.id,props.application.version],()=>{pending.value=undefined;comment.value='';notice.value='';rows.value=[];canPublish.value=false;void load();},{immediate:true});
async function publish(){if(busy.value||disposed)return;if(!pending.value){if(!comment.value.trim())return fail('请单独填写供应商可见的审核说明，不会自动复制内部意见。');try{await ElMessageBox.confirm(`将向供应商发布申请 ${props.application.applicationNo} 的结果和单独填写的说明，发布后不可修改。确认继续？`,'发布准入结果',{type:'warning'});}catch{return;}if(disposed)return;pending.value={version:props.application.version,publicComment:comment.value.trim()};}busy.value=true;error.value='';let done=false;try{const result=await session.client.POST('/admissions/{id}/public-results',{params:{path:{id:props.application.id}},body:pending.value,signal:abort.signal});if(disposed)return;if(!result.data){if([400,403,404,409,422].includes(result.response.status))pending.value=undefined;throw new Error(result.error?.error.message??'发布结果未确认');}notice.value='准入结果已明确发布至供应商门户。';pending.value=undefined;comment.value='';done=true;}catch(e){await fail((e instanceof Error?e.message:'网络异常')+(pending.value?'；结果未知，内容已锁定，可刷新核查或重试同一发布。':'；请刷新记录后核查。'));}finally{if(!disposed)busy.value=false;}if(done&&!disposed)await load();}
onUnmounted(()=>{disposed=true;generation++;abort.abort();});
</script>
<template><section class="public-admission-results" :aria-busy="busy"><h3>准入结果对外发布</h3><p>单独填写供应商可见说明后发布。内部审核意见、金额和附件不会自动公开；历史发布记录不可覆盖，不代表当前业务放行状态。</p><div v-if="error" ref="panel" role="alert" tabindex="-1"><el-alert :title="error" type="error" :closable="false"/></div><p v-if="notice" role="status">{{notice}}</p><el-button :disabled="busy" @click="load">刷新结果发布记录</el-button>
 <el-form v-if="canPublish||pending" label-position="top" @submit.prevent="publish"><el-form-item label="供应商可见准入说明"><el-input v-model="comment" type="textarea" maxlength="1000" :rows="4" show-word-limit :disabled="busy||!!pending"/></el-form-item><el-button type="primary" :disabled="busy" @click="publish">{{pending?'重试同一准入结果发布':'确认发布准入结果'}}</el-button></el-form><p v-else-if="!busy&&!rows.length">当前没有可发布结果或本账号没有发布权限；历史内部意见不会自动公开。</p>
 <article v-for="row in rows" :key="row.id"><h4>{{row.applicationNo}} · {{names[row.result]}}</h4><p>采购类别：{{row.purchaseCategory}}</p><p>发布时间（北京时间）：{{new Date(row.publishedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}}</p><p class="comment">对外说明：{{row.publicComment}}</p></article>
</section></template>
<style scoped>.public-admission-results{margin:20px 0;min-width:0;overflow-wrap:anywhere}.comment{white-space:pre-wrap;overflow-wrap:anywhere}article{padding:12px 0;border-bottom:1px solid var(--el-border-color)}</style>
